<?php
require_once __DIR__.'/../omniflow_config.php';
$db=new mysqli(DB_HOST,DB_USER,DB_PASS,DB_NAME);$db->set_charset("utf8mb4");
$w=isset($_GET['semanas'])?max(1,min(12,(int)$_GET['semanas'])):4;
if(isset($_GET['csv'])){
 header('Content-Type: text/csv; charset=utf-8');
 header('Content-Disposition: attachment; filename=analisis_'.date('Y-m-d').'.csv');
 $o=fopen('php://output','w');fputcsv($o,['Semana','Total','Trans','Info','Nav']);
 $r=$db->query("SELECT WEEK(fecha,1)s,YEAR(fecha)a,SUM(total_keywords)t,SUM(total_transaccional)tr,SUM(total_informativa)i,SUM(total_navegacion)n FROM analisis_busquedas WHERE fecha>=DATE_SUB(NOW(),INTERVAL $w WEEK) GROUP BY a,s ORDER BY a DESC,s DESC LIMIT $w");
 while($d=$r->fetch_assoc())fputcsv($o,["Sem {$d['s']}/{$d['a']}",(int)$d['t'],(int)$d['tr'],(int)$d['i'],(int)$d['n']]);
 fclose($o);exit;
}
$r=$db->query("SELECT WEEK(fecha,1)s,YEAR(fecha)a,SUM(total_keywords)t,SUM(total_transaccional)tr,SUM(total_informativa)i,SUM(total_navegacion)n FROM analisis_busquedas WHERE fecha>=DATE_SUB(NOW(),INTERVAL $w WEEK) GROUP BY a,s ORDER BY a DESC,s DESC LIMIT $w");
$data=[];$lab=[];$td=[];$idd=[];$nd=[];
while($d=$r->fetch_assoc()){
 $l="Sem {$d['s']}/{$d['a']}";$data[]=['l'=>$l,'t'=>(int)$d['t'],'tr'=>(int)$d['tr'],'in'=>(int)$d['i'],'nv'=>(int)$d['n']];
 $lab[]=$l;$td[]=(int)$d['tr'];$idd[]=(int)$d['i'];$nd[]=(int)$d['n'];
}
$data=array_reverse($data);$lab=array_reverse($lab);$td=array_reverse($td);$idd=array_reverse($idd);$nd=array_reverse($nd);
$tot=array_sum(array_column($data,'t'));$Ttr=array_sum(array_column($data,'tr'));$Tin=array_sum(array_column($data,'in'));$Tnv=array_sum(array_column($data,'nv'));
$db->close();
?><!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"><title>Reporte Keywords | PSF</title><script src="https://cdn.tailwindcss.com"></script><script src="https://cdn.jsdelivr.net/npm/chart.js@4"></script></head><body class="bg-gray-100 min-h-screen font-sans"><div class="max-w-6xl mx-auto px-4 py-8"><h1 class="text-2xl font-bold text-gray-900 mb-1">📊 Reporte Semanal de Keywords</h1><p class="text-sm text-gray-500 mb-6">Últimas <?=$w?> semanas · <a href="?csv=1&semanas=<?=$w?>" class="text-blue-600 hover:underline">📥 Exportar CSV</a> · <a href="/clasificar" class="text-blue-600 hover:underline ml-2">🔍 Clasificar</a></p><div class="grid md:grid-cols-4 gap-4 mb-8"><div class="bg-white rounded-xl shadow-sm border p-5 text-center"><div class="text-3xl font-extrabold"><?=number_format($tot)?></div><div class="text-sm text-gray-500">Total</div></div><div class="bg-green-50 rounded-xl border border-green-200 p-5 text-center"><div class="text-3xl font-extrabold text-green-700"><?=number_format($Ttr)?></div><div class="text-sm text-green-600">💰 Trans.</div><div class="text-xs text-gray-400"><?=round($Ttr/max(1,$tot)*100)?>%</div></div><div class="bg-blue-50 rounded-xl border border-blue-200 p-5 text-center"><div class="text-3xl font-extrabold text-blue-700"><?=number_format($Tin)?></div><div class="text-sm text-blue-600">📚 Info.</div><div class="text-xs text-gray-400"><?=round($Tin/max(1,$tot)*100)?>%</div></div><div class="bg-gray-50 rounded-xl border p-5 text-center"><div class="text-3xl font-extrabold text-gray-600"><?=number_format($Tnv)?></div><div class="text-sm text-gray-500">🧭 Nav.</div><div class="text-xs text-gray-400"><?=round($Tnv/max(1,$tot)*100)?>%</div></div></div><div class="bg-white rounded-2xl shadow-sm border p-6 mb-8"><canvas id="ch" height="120"></canvas></div><div class="bg-white rounded-2xl shadow-sm border overflow-hidden"><table class="w-full text-sm"><thead class="bg-gray-50 border-b"><tr><th class="text-left py-3 px-4">Semana</th><th class="text-right py-3 px-4">Total</th><th class="text-right py-3 px-4">💰</th><th class="text-right py-3 px-4">📚</th><th class="text-right py-3 px-4">🧭</th></tr></thead><tbody><?php foreach($data as $s):?><tr class="border-b hover:bg-gray-50"><td class="py-2.5 px-4 font-medium"><?=$s['l']?></td><td class="py-2.5 px-4 text-right"><?=number_format($s['t'])?></td><td class="py-2.5 px-4 text-right text-green-700"><?=number_format($s['tr'])?></td><td class="py-2.5 px-4 text-right text-blue-700"><?=number_format($s['in'])?></td><td class="py-2.5 px-4 text-right text-gray-500"><?=number_format($s['nv'])?></td></tr><?php endforeach;?></tbody></table></div></div><script>new Chart(document.getElementById('ch'),{type:'line',data:{labels:<?=json_encode($lab)?>,datasets:[{label:'💰 Trans.',data:<?=json_encode($td)?>,borderColor:'#16a34a',tension:0.3},{label:'📚 Info.',data:<?=json_encode($idd)?>,borderColor:'#2563eb',tension:0.3},{label:'🧭 Nav.',data:<?=json_encode($nd)?>,borderColor:'#6b7280',tension:0.3}]},options:{responsive:true,plugins:{legend:{position:'bottom'}},scales:{y:{beginAtZero:true,ticks:{precision:0}}}}});</script></body></html>